class RetryServer{SOCKET listener=INVALID_SOCKET;std::thread worker;std::atomic_bool stop{false};public:int port;std::atomic_int bad{0},good{0},always{0},failureStatus{404};std::atomic_bool allow{false};RetryServer(){listener=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);if(bind(listener,(sockaddr*)&a,sizeof(a))||listen(listener,16))throw std::runtime_error("Server bind failed");int n=sizeof(a);getsockname(listener,(sockaddr*)&a,&n);port=ntohs(a.sin_port);worker=std::thread([&]{while(!stop){fd_set f;FD_ZERO(&f);FD_SET(listener,&f);timeval t{0,100000};if(select(0,&f,nullptr,nullptr,&t)<=0)continue;auto s=accept(listener,nullptr,nullptr);DWORD timeout=2000;setsockopt(s,SOL_SOCKET,SO_RCVTIMEO,(char*)&timeout,sizeof(timeout));std::string request;char buf[4096];while(request.find("\r\n\r\n")==std::string::npos&&request.size()<32768){int k=recv(s,buf,sizeof(buf),0);if(k<=0)break;request.append(buf,k);}bool fail=false;if(request.find(" /always ")!=std::string::npos){++always;fail=true;}else if(request.find(" /bad ")!=std::string::npos){++bad;fail=!allow;}else ++good;std::string body=fail?"missing":std::string(8192,'G');std::string response=std::string("HTTP/1.1 ")+(fail?(std::to_string(failureStatus.load())+" Rejected"):std::string("200 OK"))+"\r\nContent-Length: "+std::to_string(body.size())+"\r\nContent-Type: application/octet-stream\r\nConnection: close\r\n\r\n"+body;size_t sent=0;while(sent<response.size()){int k=send(s,response.data()+sent,(int)(response.size()-sent),0);if(k<=0)break;sent+=k;}shutdown(s,SD_BOTH);closesocket(s);}});}~RetryServer(){stop=true;if(worker.joinable())worker.join();closesocket(listener);}std::string url(const char*p){return "http://127.0.0.1:"+std::to_string(port)+p;}};
int wmain(int argc,wchar_t**argv){if(argc!=2)return 2;fs::path root=argv[1];if(fs::exists(root))return 3;fs::create_directories(root);WSADATA w{};WSAStartup(MAKEWORD(2,2),&w);CoInitializeEx(nullptr,COINIT_MULTITHREADED);Json checks=Json::array();std::string error;auto check=[&](bool ok,const char*n){checks.push_back({{"name",n},{"passed",ok}});if(!ok)throw std::runtime_error(n);};try{RetryServer server;Manager m(root/L"data");auto prefs=m.state["Settings"];prefs["DownloadFolder"]=utf8((root/L"files").wstring());prefs["CategoryFolders"]=false;prefs["Connections"]=1;prefs["Parallel"]=1;prefs["Retries"]=0;m.setSettings(prefs);auto pump=[&](auto ready,const char*label){auto start=epoch();while(epoch()-start<15000){m.tick();{Lock lock(m.mutex);if(ready())return;}Sleep(20);}throw std::runtime_error(label);};auto q=defaultQueue();q["FileRetryLimitEnabled"]=true;q["FileRetries"]=1;q["RetryDelaySeconds"]=1;q["FinishAction"]="Exit UDM";m.setQueue(q);auto failed=m.add(server.url("/always"),"","failed.bin"),good=m.add(server.url("/good"),"","good.bin");m.queueRun("Main queue",true);pump([&]{return num(failed->data,"QueueAttempts")==1&&str(failed->data,"Status")=="Failed"&&!m.isActive(failed)&&str(good->data,"Status")=="Complete"&&!m.isActive(good);},"Bounded queue did not finish");m.tick();auto events=m.takeQueueCompletions();check(events.size()==1&&num(events[0],"FailedFiles")==1,"Explicit retry exhaustion emits one finish event with failed-file count");check(str(failed->data,"Status")=="Failed"&&str(good->data,"Status")=="Complete","Finishing processing preserves truthful per-file outcomes");check(m.completionReady("Main queue"),"Completion countdown accepts exhausted bounded queue");check(queueCompletionMessage(events[0]).find("1 file failed")!=std::string::npos&&queueCompletionMessage(events[0]).find("completed successfully")==std::string::npos,"Completion message discloses failed file rather than claiming success");std::vector<std::string> invoked;executeQueueCompletion(events[0],[&]{return m.completionReady("Main queue");},[&](const std::string& action,bool,const std::string&){invoked.push_back(action);});check(invoked==std::vector<std::string>{"Exit UDM"},"Configured action reaches recording callback without executing system action");m.tick();check(m.takeQueueCompletions().empty(),"Finished queue does not repeat action event");m.queueRun("Main queue",false);check(!m.completionReady("Main queue"),"Manual Stop cancels an already-issued completion countdown");invoked.clear();executeQueueCompletion(events[0],[&]{return m.completionReady("Main queue");},[&](const std::string&a,bool,const std::string&){invoked.push_back(a);});check(invoked.empty(),"Canceled countdown cannot dispatch action");
 q["FileRetryLimitEnabled"]=false;m.setQueue(q);m.queueRun("Main queue",true);pump([&]{return num(failed->data,"QueueAttempts")>=1&&str(failed->data,"Status")=="Queued"&&!m.isActive(failed);},"Unlimited retry not pending");check(!m.completionReady("Main queue")&&m.takeQueueCompletions().empty(),"Unlimited pending retries prevent finish action");m.queueRun("Main queue",false);check(m.takeQueueCompletions().empty(),"Stopping unfinished queue emits no finish action");
 q["FileRetryLimitEnabled"]=true;q["FileRetries"]=0;m.setQueue(q);server.failureStatus=401;m.queueRun("Main queue",true);pump([&]{return str(failed->data,"Status")=="Failed"&&!m.isActive(failed);},"Authentication failure timeout");m.tick();check(!m.completionReady("Main queue")&&m.takeQueueCompletions().empty(),"Credential rejection is not counted as exhausted completed work");m.queueRun("Main queue",false);
 auto once=defaultQueue("Once finish");once["RunOnce"]=true;once["StartOnceUtc"]=date(epoch()-1000);once["StopOnceUtc"]=date(epoch()+60000);once["FinishAction"]="Exit UDM";m.setQueue(once);auto one=m.add(server.url("/good"),"","once.bin","Once finish");m.queueRun("Once finish",true);pump([&]{return str(one->data,"Status")=="Complete"&&!m.isActive(one);},"Once queue timeout");m.tick();events=m.takeQueueCompletions();bool disabled=false;for(auto value:m.state["Queues"])if(str(value,"Name")=="Once finish")disabled=!yes(value,"Enabled");check(disabled&&events.size()==1&&m.completionReady("Once finish"),"Automatic one-time disarming still allows its completion action");check(queueCompletionMessage(events[0]).find("completed successfully")!=std::string::npos,"Successful queue retains success message");m.queueRun("Once finish",false);check(!m.completionReady("Once finish"),"Explicit Stop distinguishes cancellation from one-time disarming");m.stop();
 }catch(const std::exception&e){error=e.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"error",error},{"checks",checks},{"systemActionsExecuted",false}}.dump(2),false);CoUninitialize();WSACleanup();return error.empty()?0:1;}